:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --text: #e0e0f0;
  --text-muted: #a0a0b8;
  --accent: #7c9aff;
  --accent-hover: #9ab0ff;
  --accent-pressed: #5a7ae0;
  --border: #3a3a50;
  --radius: 12px;
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background-image: radial-gradient(circle at 20% 20%, #2e2e48 0%, transparent 50%),
                    radial-gradient(circle at 80% 80%, #2a2a40 0%, transparent 50%);
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px;
  width: 100%;
  max-width: 540px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  line-height: 1.5;
  margin-top: -12px;
}

.swatches {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 16px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 10px;
  padding: 12px;
  transition: background 0.15s ease;
}

.swatch:hover {
  background: rgba(255, 255, 255, 0.08);
}

.swatch-color {
  width: 56px;
  height: 56px;
  border-radius: 8px;
  flex-shrink: 0;
  border: 2px solid rgba(255, 255, 255, 0.1);
  transition: background-color 0.3s ease;
}

.swatch-info {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  min-width: 0;
}

.hex-code {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.lock-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  font-size: 0.875rem;
  color: var(--text-muted);
  user-select: none;
  width: fit-content;
  padding: 2px 4px;
  border-radius: 4px;
  transition: color 0.15s ease;
}

.lock-label:hover {
  color: var(--text);
}

.lock-label:focus-within {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.lock-toggle {
  appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid var(--text-muted);
  border-radius: 4px;
  cursor: pointer;
  position: relative;
  transition: background 0.15s ease, border-color 0.15s ease;
  flex-shrink: 0;
}

.lock-toggle:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.lock-toggle:checked::after {
  content: '';
  position: absolute;
  left: 4px;
  top: 1px;
  width: 5px;
  height: 9px;
  border: solid var(--bg);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.lock-toggle:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.lock-text {
  font-size: 0.8rem;
}

.generate-btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 14px 24px;
  border: none;
  border-radius: 10px;
  background: var(--accent);
  color: #0e0e1a;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  width: 100%;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

.generate-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 3px;
}

@media (max-width: 420px) {
  .card {
    padding: 20px;
  }

  .swatch-color {
    width: 44px;
    height: 44px;
  }

  .hex-code {
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  var SWATCH_COUNT = 5;
  var swatchesEl = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');
  var template = document.getElementById('swatch-template');

  // Store current palette colors and lock states
  var colors = [];
  var locked = [];

  // ---- Color helpers ----

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;

    if (h < 60) { r = c; g = x; }
    else if (h < 120) { r = x; g = c; }
    else if (h < 180) { g = c; b = x; }
    else if (h < 240) { g = x; b = c; }
    else if (h < 300) { r = x; b = c; }
    else { r = c; b = x; }

    r = Math.round((r + m) * 255);
    g = Math.round((g + m) * 255);
    b = Math.round((b + m) * 255);

    return (
      '#' +
      r.toString(16).padStart(2, '0') +
      g.toString(16).padStart(2, '0') +
      b.toString(16).padStart(2, '0')
    );
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  // Generate a harmonious palette using an analogous + accent scheme
  function generatePalette() {
    var baseHue = randomInt(0, 359);
    var scheme = randomInt(0, 2); // 0: analogous, 1: complementary, 2: triadic
    var hues = [];

    if (scheme === 0) {
      // Analogous: hues close together
      for (var i = 0; i < SWATCH_COUNT; i++) {
        hues.push((baseHue + i * 24) % 360);
      }
    } else if (scheme === 1) {
      // Complementary with variations
      hues = [
        baseHue,
        (baseHue + 30) % 360,
        (baseHue + 180) % 360,
        (baseHue + 210) % 360,
        (baseHue + 150) % 360
      ];
    } else {
      // Triadic with variations
      hues = [
        baseHue,
        (baseHue + 120) % 360,
        (baseHue + 240) % 360,
        (baseHue + 60) % 360,
        (baseHue + 300) % 360
      ];
    }

    var newColors = [];
    for (var j = 0; j < SWATCH_COUNT; j++) {
      var h = hues[j];
      var s = randomInt(55, 85);
      var l = randomInt(40, 70);
      newColors.push(hslToHex(h, s, l));
    }
    return newColors;
  }

  // ---- Rendering ----

  function render() {
    swatchesEl.innerHTML = '';

    for (var i = 0; i < SWATCH_COUNT; i++) {
      var clone = template.content.cloneNode(true);
      var li = clone.querySelector('.swatch');
      var colorBox = clone.querySelector('.swatch-color');
      var hexEl = clone.querySelector('.hex-code');
      var checkbox = clone.querySelector('.lock-toggle');

      var color = colors[i];
      var isLocked = locked[i];

      colorBox.style.backgroundColor = color;
      hexEl.textContent = color.toUpperCase();
      checkbox.checked = isLocked;

      // Accessibility
      checkbox.setAttribute('aria-label', 'Lock color ' + color.toUpperCase());
      li.setAttribute('data-index', i);

      // Event listener for lock toggle
      (function (index, cb) {
        cb.addEventListener('change', function () {
          locked[index] = cb.checked;
          var hex = colors[index].toUpperCase();
          cb.setAttribute(
            'aria-label',
            (cb.checked ? 'Unlock' : 'Lock') + ' color ' + hex
          );
        });
      })(i, checkbox);

      swatchesEl.appendChild(clone);
    }
  }

  // ---- Actions ----

  function updatePalette() {
    var newColors = generatePalette();
    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (!locked[i]) {
        colors[i] = newColors[i];
      }
    }
    render();
  }

  function init() {
    colors = generatePalette();
    locked = [false, false, false, false, false];
    render();

    generateBtn.addEventListener('click', updatePalette);
  }

  init();
})();
